/**
 * Two Copilot skill files exactly as an earlier dr shipped them (integrations/github_copilot/skills/
 * at the parent of commit 687c4fab), base64-encoded so commit hooks that fix whitespace leave the
 * bytes alone. Tests write them into a project to stand for leftovers of an older integration
 * layout: `dr upgrade` offers an entry as a leftover only when its contents match a version in
 * cli/src/integrations/shipped-entries.ts.
 */
export const SHIPPED_COPILOT_SKILLS: Record<string, string> = {
  dr_layer_02_business: "",
  dr_layer_04_app: "",
};

/** The shipped contents of a skill folder's SKILL.md */
export function shippedSkill(name: string): Buffer {
  return Buffer.from(SHIPPED_COPILOT_SKILLS[name], "base64");
}
